import json

def load(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.load_asset', json.dumps({'asset_path': path}))['returnValue']

def get(instance, properties):
    value = execute_tool('editor_toolset.toolsets.object.ObjectTools.get_properties', json.dumps({'instance': instance, 'properties': properties}))['returnValue']
    return json.loads(value)

def dirty(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.is_dirty', json.dumps({'asset_path': path}))['returnValue']

def run():
    paths = [
        '/ExtractionOps/Input/IA_ExtractionInteract',
        '/ExtractionOps/Input/IMC_Extraction',
        '/ExtractionOps/Input/DA_ExtractionInputAddOns',
        '/ExtractionOps/Experiences/DA_ExtractionInputActionSet',
        '/ExtractionOps/Experiences/B_ExtractionExperience'
    ]
    dirty_assets = [path for path in paths if dirty(path)]
    if dirty_assets:
        raise RuntimeError('Unsaved input assets: ' + ', '.join(dirty_assets))
    mapping_data = get(load('/ExtractionOps/Input/IMC_Extraction'), ['defaultKeyMappings'])['defaultKeyMappings']['mappings']
    interact_mappings = [mapping for mapping in mapping_data if 'IA_ExtractionInteract' in str(mapping.get('action', ''))]
    addons = get(load('/ExtractionOps/Input/DA_ExtractionInputAddOns'), ['abilityInputActions'])['abilityInputActions']
    interact_actions = [action for action in addons if action.get('inputTag', {}).get('tagName') == 'InputTag.Ability.Interact']
    experience = get(load('/ExtractionOps/Experiences/B_ExtractionExperience'), ['actionSets'])['actionSets']
    if len(interact_mappings) != 1 or str(interact_mappings[0].get('key')) != 'F':
        raise RuntimeError('Interact must have exactly one F-key mapping')
    if len(interact_actions) != 1:
        raise RuntimeError('Interact must have exactly one InputConfig binding')
    if not any('DA_ExtractionInputActionSet' in str(action_set) for action_set in experience):
        raise RuntimeError('Extraction Experience does not reference the input action set')
    return {
        'dirty': dirty_assets,
        'interactMapping': interact_mappings[0],
        'interactInputBinding': interact_actions[0],
        'experienceActionSets': experience
    }
